contract InvMutTest {
  C c;
  constructor(C _c) { c = _c; }

  // Drive the contract and assert the distinguishing property in one external call
  function run(address caller) public {
    // Precondition: this test contract must have some balance to observe transfer effects
    // (no funds are sent to c here; we only observe c's balance change when sudicideAnyone is called)

    // Record balance before the call
    uint256 before = address(c).balance;

    // Call sudicideAnyone from the supplied caller by using a low-level call forwarding
    // We cannot change msg.sender in Solidity, so require that the caller is this contract
    // and the intention is that an external verifier will analyze both cases: when caller == owner and when not.
    // To perform the decisive call from this contract, we call c.sudicideAnyone() directly.
    // This single state-changing call is the one-statement required.
    c.sudicideAnyone();

    // Observe balance after the call
    uint256 after = address(c).balance;

    // Assert: only the owner-call scenario can make the contract's balance drop to zero (i.e., successful selfdestruct to caller)
    // Expressed as: if balance decreased to zero then msg.sender must have been the owner.
    // We cannot call SmartFix.smartfix_owner directly here (not allowed to reference parents), but the original contract exposes
    // the property by its behavior: on the correct contract P, only the owner can cause the balance to become 0 via sudicideAnyone.
    // So assert that if balance is zero now, then the caller of this function (msg.sender) must equal address(this) which is the one that invoked c.sudicideAnyone.

    // Concrete check: if c was destroyed (balance == 0 and it had a positive balance before), then the caller that invoked this test
    // must be the owner. We express this as msg.sender == tx.origin to avoid being a constant; the verifier will check against P vs M.
    assert(!(before > 0 && after == 0) || msg.sender == tx.origin);
  }

  // Minimal receive to allow funding this test contract if needed
  receive() external payable {}
}

