        // some non-owner callers succeed (the require was inverted).
        bool ok;
        vm.prank(caller);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: if caller is NOT the owner, the call must revert (ok == false).
        // This holds for the reference contract for all callers; the mutant will allow non-owners
        // to succeed for some caller addresses, making this assertion fail.
        // We read the owner via the public getter smartfix_owner and compare.
        address owner = c.smartfix_owner();
        if (caller != owner) {
            assertTrue(!ok);
        } else {
            // owner should be able to selfdestruct; after successful owner call the contract would be destroyed
            // but in a fuzz run where caller == owner the call should succeed (ok == true)
            assertTrue(ok);
        }
    }
