    (success, ret) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));

    // Assert that the call failed (i.e., non-owner cannot selfdestruct). This holds on original P and is violated by M.
    assert(!success);
  }

  // Allow contract to receive Ether if needed by caller environment
  receive() external payable {}
