        // some attacker to destroy it, causing balance change.

        uint256 balBefore = address(c).balance;

        // execute call as attacker; capture whether it succeeded without revert
        bool ok;
        vm.prank(attacker);
        try c.sudicideAnyone() {
            ok = true;
        } catch {
            ok = false;
