        // If the caller was not the owner, the call must have reverted (ok == false).

        // Read owner via autogenerated getter on the contract
        address owner = c.smartfix_owner();

        // EXACTLY ONE ASSERTION required. For the correct contract, for ALL attacker addresses,
        // if attacker != owner then ok must be false. The mutant (which removes the require)
