contract InvMutTest {
  C public c;
  constructor(C _c) { c = _c; }

  // single public test function performing the minimal interactions
  // params: caller address (who will invoke sudicideAnyone) and a boolean indicating
  // whether we expect the caller to be the owner. We don't assume who the owner is;
  // we only assert that if the contract still exists after the call, the caller must
  // have been the owner when destruction was attempted. For P this holds; for M it breaks.
  function runTest(address caller) public {
    // call sudicideAnyone as the provided caller
    // Use low-level call to set msg.sender to this contract; instead we simulate by
    // having this contract call c.sudicideAnyone() and then observe whether c's balance
    // or existence changed. However C's selfdestruct sends Ether to msg.sender and
    // ends the target contract. We can observe by checking address(c).balance before/after.

    // Ensure we have some balance to make the effect observable (not required but harmless).
    // No Ether transfer is performed to c in this test; we rely on destruction observable via code size.

    // Record code size (existence) of c before the call using address(c).balance is allowed; but
    // we can use address(c).balance and also check that call succeeds or not. The essential distinguishing
    // behaviour: on P, only owner can selfdestruct, so when non-owner calls sudicideAnyone it will revert
    // and c will remain; on M, the call will succeed for anyone and c will be destroyed. We capture
    // the revert boolean of the call and the post-call existence.

    // Make the call as this contract; to simulate different callers, the verifier will provide different
    // deployments of InvMutTest under different addresses — here we just perform the call.
    (bool ok, ) = address(c).call(abi.encodeWithSignature("sudicideAnyone()"));

    // Check whether contract c still exists by performing a staticcall to a public getter: smartfix_owner() is public.
    // If the contract has been destroyed, the call will return false / empty. We use a low-level staticcall.
    (bool exists, bytes memory data) = address(c).staticcall(abi.encodeWithSignature("smartfix_owner()"));

    // If the contract still exists then the original contract enforced the require and the call should have succeeded only when msg.sender==smartfix_owner.
    // We assert: if c still exists then either the sudicideAnyone call reverted (ok==false) OR the caller equals smartfix_owner.
    // For P: non-owner call reverts, so ok==false and assertion holds. Owner call may succeed and smartfix_owner==caller so holds.
    // For M: call succeeds for non-owner (ok==true) and contract destroyed (exists==false) so antecedent false and assertion vacuously holds — but we need the rule violated by M.

    // To ensure violation on M, we assert that WHEN the contract still exists after the call, then either the call reverted OR the caller equals the stored owner.
    // On P this always holds. On M, a non-owner call will succeed and destroy the contract, making exists==false; that does not violate the assertion.
    // However the distinguishing condition required is that M allows destruction by non-owner: so we need to observe existence==false while caller != owner. We convert the rule to
    // assert that IF the call succeeded (ok==true) THEN the caller must equal the stored owner (read from data). This will hold on P (only owner can succeed) and be violated on M (non-owner call succeeds).

    // Decode owner if exists; if not exists data may be empty — in that case we set owner to zero.
    address owner = address(0);
    if (exists && data.length >= 32) {
      owner = abi.decode(data, (address));
    }

    assert(!ok || owner == address(this));
  }

  // fallback and receive are allowed but not needed
  receive() external payable {}
}

