pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed param is the caller address that will be the owner (smartfix_owner)
    function testFuzz_property(address caller) public {
        // keep caller non-zero to be a sensible actor
        vm.assume(caller != address(0));

        // fund the contract with some ether so transfers on selfdestruct matter
        uint256 fund = 1 ether;
        vm.deal(address(this), fund);
        // send funds to contract
        (bool sent, ) = address(c).call{value: fund}(" ");
        // allow the send; if it fails the test setup is invalid
        assumeBool(sent);

        // ensure the fuzzed caller is the stored owner by deploying c in setUp (owner is deployer)
        // we need caller to be the owner (smartfix_owner == msg.sender) when calling sudicideAnyone.
        // The contract's owner was set to msg.sender at deployment (setUp used this address), so to make
        // 'caller' the owner we must instead impersonate the deployer. The deployer is address(this) as
        // new C() was called in setUp from this contract. So require the fuzzed caller equals the deployer.
        // To satisfy the requirement that the test uses a fuzzed parameter as a deciding value, we will
        // treat 'caller' as the actor that will invoke sudicideAnyone; but only when it equals the deployer
        // will the call succeed and lead to selfdestruct. We therefore bound the fuzzed space by assuming
        // caller == address(this) or otherwise the call will revert due to require. Keep wide domain by
        // allowing both but only exercising the destructive path when equal.

        // Record balances before call
        uint256 contractBalBefore = address(c).balance;
        uint256 callerBalBefore = caller.balance;

        bool ok;
        // If caller is the deployer (owner), calling will pass the require and trigger selfdestruct.
        vm.prank(caller);
        try c.sudicideAnyone{value: 0}() {
            ok = true;
        } catch {
            ok = false;
        }

        // After call: if ok==true then selfdestruct executed (in correct contract) and contract balance must be zero
        // and caller must have gained the funds. The single assertion reads c via address(c).balance and caller balance.
        // We assert that either the call did not execute (ok == false) OR (call executed and contract balance is zero
        // and caller received the prior contract balance). This universal property holds for the reference: when owner
        // calls, caller (owner) receives funds. The mutant that directs funds to stored owner different from caller will
        // make this assertion fail for inputs where caller==address(this) (owner) vs other cases; fuzz will find cases.
        if (ok) {
            assertTrue(address(c).balance == 0 && caller.balance >= callerBalBefore + contractBalBefore);
        } else {
            // call didn't execute (e.g., caller wasn't owner). Ensure at least contract balance unchanged.
            assertTrue(address(c).balance == contractBalBefore);
        }
    }

    // helper to convert bool from low-level call to vm.assume-friendly form
    function assumeBool(bool b) internal pure {
        if (!b) revert();
    }
}

